import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`lash-studio-audit`,heroTitle:`Audit your lash studio in minutes`,heroSubtitle:`Perplexity Computer reviews your lash studio site, booking flow, reviews, offers, and local visibility to find the fastest path to more appointments.`,inputUrlCta:`Audit my studio`,inputUrlPlaceholder:`yourlashstudio.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this lash studio. 1) Review the website for service clarity, pricing presentation, before-and-after proof, artist credibility, booking flow, mobile usability, and CTA quality. 2) Analyze Google Business Profile, reviews, local SEO, Instagram signals, and competitor studios nearby. 3) Identify trust gaps, missed upsell opportunities, weak service positioning, and friction in the booking path. 4) Rewrite priority copy for the homepage, service menu, and booking CTA. 5) Deliver a prioritized action plan to increase booked appointments.`,heroOverlaySteps:[`Reviewing your services, pricing, proof, and booking flow for conversion gaps`,`Checking reviews, local search visibility, Instagram signals, and nearby studios`,`Rewriting service messaging and prioritizing fixes that drive appointments`,`Booking-flow improvements and local growth plan ready to use`],generatingSteps:[`Visiting {url} to review your lash studio site, service menu, and booking path`,`Designing an agent to analyze reviews, local visibility, and competitor studios`,`Configuring copy rewrites, offer positioning, and conversion recommendations`,`Setting up a prioritized action plan for more booked appointments`],featureSectionTitle:`From profile visits to booked lash appointments`,featureCardTitles:[`Connects your booking signals`,`Fixes you can launch today`],featureCardDescriptions:[`Computer separates site review, booking-flow analysis, local SEO, review analysis, and competitor benchmarking.`,`Google Business Profile, Instagram, booking pages, Docs, and Sheets can feed one workflow so studio growth work stays organized.`,`Homepage copy. Service-menu fixes. Local SEO priorities. Booking CTA improvements. Computer gives you updates tied to more appointments.`],capabilitySectionTitle:`Your lash studio growth team, on autopilot`,capabilitySectionSubtitle:`Paste your lash studio URL and get back a prioritized plan to drive more bookings.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review service clarity, pricing presentation, artist credibility, before-and-after proof, mobile UX, and booking friction.`},{title:`Local Search Review`,description:`Computer can assess your Google Business Profile, reviews, local SEO setup, and Instagram signals against nearby competitors.`},{title:`Offer Positioning`,description:`Computer can rewrite service messaging, booking CTAs, and upsell prompts so prospects know what to book and why.`},{title:`Connect Your Tools`,description:`Computer can organize findings across Google Business Profile, Instagram notes, Docs, Sheets, and your booking system.`},{title:`Remember Your Services`,description:`Computer can remember your service menu, pricing, ideal client, and strongest proof so future audits stay tailored.`},{title:`Monitor Booking Signals`,description:`Computer can revisit your online presence over time, flag when conversion signals slip, and suggest the next fix.`}]});export{t as default};
